/**
 * Texas held-source inventory — deterministic generator and clean-checkout validator.
 *
 * WHY THIS EXISTS. For part of the Principles II build, the list of held sources lived in a
 * gitignored scratch file, .prins2-drafts/HELD-SOURCE-HASHES.txt. That file was generated by a glob
 * covering only statutes/ and federal/, so it silently omitted trec-rules/ and articles/ — and the
 * Principles II source register, correctly refusing to invent a hash for a source its manifest did
 * not carry, excluded 22 TAC §§ 535.55/.62/.63/.64/.65 and the TREC buyer-representation article
 * even though every one of those files was on disk and already hashed in a committed artifact.
 *
 * The register behaved correctly. The INPUT was wrong, and the input was untracked, so nothing in
 * the repository could have caught it. This script replaces that scratch file with a committed,
 * reproducible mechanism whose output is itself committed, so the same defect cannot recur silently.
 *
 * WHAT IT GUARANTEES.
 *   - The inventory covers EVERY file under texas/trec-sources, recursively. No glob to forget a
 *     directory: the walk is the definition, and a new source directory is picked up automatically.
 *   - Every hash in the tracked inventory is recomputed from the file on disk.
 *   - Every source a committed register or lock names is present in the inventory with a matching
 *     hash and byte count.
 *   - Every CONTROLLING source — one the curriculum, assessment logic or compliance logic relies on
 *     directly — has an inventory entry. A controlling source without one fails the run.
 *   - It reads nothing from .prins2-drafts/ or any other scratch location, so it passes or fails
 *     identically on a clean checkout.
 *
 * REPRODUCE THE VALIDATION (clean checkout, no scratch directory required):
 *
 *     node scripts/texas-source-inventory.mjs
 *
 * Exit status 0 means the tracked inventory matches disk and every registered and controlling
 * source resolves. Non-zero means one of those failed and the run prints which.
 *
 * REGENERATE the tracked inventory after adding or refreshing a source:
 *
 *     node scripts/texas-source-inventory.mjs --write
 *
 * The written artifact is texas/trec-sources/source-inventory.json, which IS tracked. Regenerating
 * it is a reviewable diff: a changed hash shows up as a changed line.
 */

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE_ROOT = path.join(root, "texas/trec-sources");
const INVENTORY = path.join(SOURCE_ROOT, "source-inventory.json");

const WRITE = process.argv.includes("--write");

/* ── the walk IS the definition of "held" ─────────────────────────────────────────────────────
   Recursive, sorted, and deliberately not a glob over named subdirectories — that is exactly the
   mistake this file exists to prevent. */
function walk(dir, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, out);
    else if (entry.isFile() && path.resolve(full) !== path.resolve(INVENTORY)) out.push(full);
  }
  return out;
}

function digest(file) {
  const buf = fs.readFileSync(file);
  return { sha256: crypto.createHash("sha256").update(buf).digest("hex"), bytes: buf.length };
}

function buildInventory() {
  const files = walk(SOURCE_ROOT);
  const entries = files.map((full) => {
    const rel = path.relative(root, full).split(path.sep).join("/");
    return { path: rel, ...digest(full) };
  });
  entries.sort((a, b) => a.path.localeCompare(b.path));
  return {
    generatedBy: "scripts/texas-source-inventory.mjs",
    reproduceWith: "node scripts/texas-source-inventory.mjs",
    regenerateWith: "node scripts/texas-source-inventory.mjs --write",
    note: "Every file held under texas/trec-sources, walked recursively. Hashes are recomputed from disk; nothing here is transcribed by hand or carried over from another register.",
    fileCount: entries.length,
    totalBytes: entries.reduce((a, e) => a + e.bytes, 0),
    files: entries,
  };
}

/* ── which sources are CONTROLLING ────────────────────────────────────────────────────────────
   A controlling source is one the curriculum, the assessment logic or the compliance logic relies
   on directly, such that the course could not stand without it. These are named explicitly rather
   than inferred, because the point of the check is to notice when one goes missing.

   22 TAC §§ 535.62 and 535.65 are controlling for the ASSESSMENT design specifically: the
   topic-quiz minimum, the scenario count, the four examination versions, the per-version and bank
   question counts, the true/false prohibition, the one-third overlap cap and the 70% unweighted
   passing score are all derived from them in config/texas/trec-rules-source-lock.mjs. Occupations
   Code chs. 1101 and 1103 are NOT substitutes for those administrative rules. */
const CONTROLLING = [
  { path: "texas/trec-sources/trec-rules/535.55.txt", why: "sales agent qualifying-education requirement, and the rule that fixes Law of Agency at 30 credit hours — the multiplicand in every per-hour assessment count" },
  { path: "texas/trec-sources/trec-rules/535.62.txt", why: "course approval; (b)(7) fixes the topic-quiz and scenario counts and the distance-education gating, and (b)(8) fixes every final-examination count, for Principles II and Law of Agency alike" },
  { path: "texas/trec-sources/trec-rules/535.63.txt", why: "instructor qualification — a condition of course approval and of § 535.65(g)(2)(D), which makes a qualified instructor responsible for the rationale behind grading" },
  { path: "texas/trec-sources/trec-rules/535.64.txt", why: "adopts PRINS 1-1, PRINS 2-1 and LOA-1 by reference, making each outline transcription a compliance artifact and fixing the topics every examination version must cover" },
  { path: "texas/trec-sources/trec-rules/535.65.txt", why: "provider operations: 70% unweighted passing score, version rotation, examination confidentiality, identity validation, the 90-day subsequent-examination rules, four-year record retention and the completion record" },
  { path: "texas/trec-sources/PRINS2-1.pdf", why: "the Principles II course approval form itself" },
  { path: "texas/trec-sources/statutes/OC.1101.htm", why: "TRELA — the substantive law of topics T06 and T07" },
  { path: "texas/trec-sources/statutes/OC.1103.htm", why: "appraiser licensing — topic T03" },
  { path: "texas/trec-sources/statutes/PR.92.htm", why: "residential tenancies — topics T04 and T09" },
  { path: "texas/trec-sources/statutes/PR.301.htm", why: "Texas Fair Housing Act — topic T08" },
  { path: "texas/trec-sources/statutes/BC.17.htm", why: "DTPA — Principles II topic T07, and the whole of Law of Agency topic T11" },
  { path: "texas/trec-sources/statutes/LG.211.htm", why: "municipal zoning — topic T05" },
  { path: "texas/trec-sources/statutes/CN.16.htm", why: "Texas Constitution art. XVI § 50, home equity lending — topic T02" },
  { path: "texas/trec-sources/federal/us42-3604.html", why: "Fair Housing Act prohibited practices — topic T08" },
  /* Law of Agency (LOA-1). The form itself; the two rules the course cites most often after the
     statute; the DTPA chapter that is a whole LOA-1 topic; and the two employment sources whose
     scope the course is careful about. Each is relied on directly by
     config/texas/law-of-agency-statute-sources.mjs, which recomputes every hash from disk. */
  { path: "texas/trec-sources/LOA-1.pdf", why: "the Law of Agency course approval form itself, adopted by reference by 22 TAC § 535.64" },
  { path: "texas/trec-sources/trec-rules/535.2.txt", why: "broker responsibility — the rule LOA-1 topic T09 owns and nine other modules cite" },
  { path: "texas/trec-sources/trec-rules/531.20.txt", why: "adopts the IABS notice by reference — the controlling authority for LOA-1 unit T02U5, which the form itself is not" },
  { path: "texas/trec-sources/forms/IABS-1-2.pdf", why: "the instrument 22 TAC § 531.20 adopts; held and identified, no taught proposition rests on it" },
  { path: "texas/trec-sources/statutes/LA.201.htm", why: "Labor Code § 201.072 — unemployment compensation coverage only, LOA-1 topic T09" },
  { path: "texas/trec-sources/federal/us26-3508.html", why: "26 U.S.C. § 3508 — federal tax treatment only, LOA-1 topic T09" },
];

/** Registers whose named sources must all resolve into the inventory. Loaded defensively: a
    register that is mid-edit should report as such rather than crash the validator. */
const REGISTERS = [
  { id: "trec-rules-source-lock", module: "../config/texas/trec-rules-source-lock.mjs", pick: (m) => (m.RULES || []).map((r) => ({ label: r.section, localCopy: r.localCopy, sha256: r.sha256, bytes: r.bytes })) },
  { id: "regulatory-manifest", module: "../config/texas/regulatory-manifest.mjs", pick: (m) => (m.SOURCES || []).filter((s) => s.localCopy && s.sha256).map((s) => ({ label: s.id, localCopy: s.localCopy, sha256: s.sha256, bytes: s.bytes })) },
  { id: "principles-ii-statute-sources", module: "../config/texas/principles-ii-statute-sources.mjs", pick: (m) => (m.ALL_SOURCES || []).filter((s) => s.localCopy && s.sha256).map((s) => ({ label: s.id || s.citation, localCopy: s.localCopy, sha256: s.sha256, bytes: s.bytes })) },
  { id: "principles-i-statute-sources", module: "../config/texas/statute-sources.mjs", pick: (m) => (m.ALL_SOURCES || []).filter((s) => s.localCopy && s.sha256).map((s) => ({ label: s.id || s.citation, localCopy: s.localCopy, sha256: s.sha256, bytes: s.bytes })) },
  { id: "law-of-agency-statute-sources", module: "../config/texas/law-of-agency-statute-sources.mjs", pick: (m) => (m.ALL_SOURCES || []).filter((s) => s.localCopy && s.sha256).map((s) => ({ label: s.id || s.citation, localCopy: s.localCopy, sha256: s.sha256, bytes: s.bytes })) },
];

async function validate() {
  const failures = [];
  const warnings = [];
  const fresh = buildInventory();

  if (!fs.existsSync(INVENTORY)) {
    failures.push(`tracked inventory missing at ${path.relative(root, INVENTORY)} — run with --write`);
    return { failures, warnings, fresh, tracked: null, registerChecks: [] };
  }
  const tracked = JSON.parse(fs.readFileSync(INVENTORY, "utf8"));
  const trackedByPath = new Map(tracked.files.map((f) => [f.path, f]));
  const freshByPath = new Map(fresh.files.map((f) => [f.path, f]));

  for (const f of fresh.files) {
    const t = trackedByPath.get(f.path);
    if (!t) { failures.push(`file on disk is absent from the tracked inventory: ${f.path}`); continue; }
    if (t.sha256 !== f.sha256) failures.push(`HASH DIFFERS from tracked inventory: ${f.path}`);
    else if (t.bytes !== f.bytes) failures.push(`byte count differs: ${f.path} (tracked ${t.bytes}, disk ${f.bytes})`);
  }
  for (const t of tracked.files) {
    if (!freshByPath.has(t.path)) failures.push(`inventory names a source that is MISSING from disk: ${t.path}`);
  }

  for (const c of CONTROLLING) {
    if (!freshByPath.has(c.path)) failures.push(`CONTROLLING source missing from disk: ${c.path} (${c.why})`);
    else if (!trackedByPath.has(c.path)) failures.push(`CONTROLLING source lacks an inventory entry: ${c.path} (${c.why})`);
  }

  const registerChecks = [];
  for (const reg of REGISTERS) {
    let mod;
    try { mod = await import(reg.module); }
    catch (error) { warnings.push(`register ${reg.id} could not be loaded (${error.message.split("\n")[0]}) — skipped`); continue; }
    let named;
    try { named = reg.pick(mod); }
    catch (error) { warnings.push(`register ${reg.id} shape unexpected (${error.message}) — skipped`); continue; }
    if (!named.length) { warnings.push(`register ${reg.id} names no hashed sources — skipped`); continue; }
    let ok = 0;
    for (const s of named) {
      const rel = s.localCopy.split(path.sep).join("/");
      const f = freshByPath.get(rel);
      if (!f) { failures.push(`${reg.id} names a source not present on disk: ${rel} (${s.label})`); continue; }
      if (f.sha256 !== s.sha256) { failures.push(`${reg.id} hash disagrees with disk for ${rel} (${s.label})`); continue; }
      if (s.bytes && f.bytes !== s.bytes) { failures.push(`${reg.id} byte count disagrees with disk for ${rel} (${s.label})`); continue; }
      ok += 1;
    }
    registerChecks.push({ register: reg.id, named: named.length, verified: ok });
  }

  return { failures, warnings, fresh, tracked, registerChecks };
}

if (WRITE) {
  const inv = buildInventory();
  fs.writeFileSync(INVENTORY, `${JSON.stringify(inv, null, 2)}\n`);
  console.log(`wrote ${path.relative(root, INVENTORY)} — ${inv.fileCount} files, ${inv.totalBytes.toLocaleString()} bytes`);
} else {
  const { failures, warnings, fresh, registerChecks } = await validate();
  console.log(`held sources on disk: ${fresh.fileCount} (${fresh.totalBytes.toLocaleString()} bytes)`);
  console.log(`controlling sources checked: ${CONTROLLING.length}`);
  for (const r of registerChecks) console.log(`  register ${r.register}: ${r.verified}/${r.named} sources verified against disk`);
  for (const w of warnings) console.log(`  note: ${w}`);
  if (failures.length) {
    console.log(`\nFAILURES (${failures.length}):`);
    for (const f of failures) console.log(`  - ${f}`);
    process.exitCode = 1;
  } else {
    console.log("\nOK — tracked inventory matches disk, every registered source resolves, every controlling source is present.");
  }
}
